const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const safe=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'CONNECT WALLET';
const validWallet=a=>typeof a==='string'&&/^0x[a-fA-F0-9]{40}$/.test(a);
const fmtDate=v=>v?new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const ART=['assets/relic/token-emblem-v2.png','assets/relic/hero-relic.png','assets/relic/card-panorama.png'];
const REGIONS=[
 {id:'forgotten-temple',name:'THE FORGOTTEN TEMPLE',difficulty:'MODERATE',civilization:'NEXUS',description:'A sunken sanctuary surrounding the first known signal.',material:'Obsidian Alloy',energy:'Solar Harmonic'},
 {id:'abyssal-archive',name:'THE ABYSSAL ARCHIVE',difficulty:'SEVERE',civilization:'THALASS',description:'A drowned repository beneath a lightless planetary sea.',material:'Abyssal Glass',energy:'Tidal Resonance'},
 {id:'ashen-city',name:'THE ASHEN CITY',difficulty:'HIGH',civilization:'KHEM-RA',description:'A glass-black metropolis preserved beneath metallic ash.',material:'Cinder Ceramic',energy:'Thermal Echo'},
 {id:'celestial-ruins',name:'THE CELESTIAL RUINS',difficulty:'EXTREME',civilization:'VESPERA',description:'Orbital monuments adrift above a fractured world.',material:'Aether Crystal',energy:'Gravitic Chorus'},
 {id:'obsidian-vault',name:'THE OBSIDIAN VAULT',difficulty:'UNKNOWN',civilization:'THE FIRST ONES',description:'A sealed chamber older than every recovered record.',material:'Voidstone',energy:'Null Pulse'}
];
const NAMES=[
 ['Echo Sphere','Temple Key','Sunken Diadem','Oracle Lens','Pilgrim Seal','Genesis Shard','Harmonic Idol','Vault Compass','Memory Bell','Astral Reliquary'],
 ['Tide Codex','Abyssal Prism','Drowned Crown','Leviathan Scale','Pressure Sigil','Pearl Engine','Trench Beacon','Silent Conch','Current Dial','Archive Pearl'],
 ['Ember Core','Ashen Mask','Cinder Scepter','Furnace Glyph','Glass Phoenix','Pyre Compass','Smolder Crown','Magma Seal','Carbon Oracle','Last Flame'],
 ['Orbit Crown','Celestial Orrery','Gravity Harp','Star Compass','Aether Wing','Sky Monolith','Lunar Seal','Comet Lens','Zenith Dial','Constellation Key'],
 ['Void Heart','Obsidian Cipher','Null Crown','Eclipse Mirror','Shadow Engine','Black Star','Sealed Eye','Night Compass','Entropy Key','Prime Monolith']
];
const CATEGORIES=['ARTIFACT','RESONATOR','ARCHIVE','NAVIGATOR','CEREMONIAL'];
const FUNCTIONS=['navigation across impossible distances','preservation of cultural memory','translation of harmonic signals','ceremonial synchronization','mapping of vanished star routes'];
const TEMPLATES=REGIONS.flatMap((region,ri)=>NAMES[ri].map((name,i)=>({templateId:`${region.id}-${i+1}`,name,regionId:region.id,region:region.name,civilization:region.civilization,category:CATEGORIES[i%5],material:region.material,energySignature:region.energy,description:`An artifact formed from ${region.material.toLowerCase()}, recovered from ${region.name.toLowerCase()}. Its markings suggest ${FUNCTIONS[i%5]}.`,history:`Archive scholars associate ${name} with the late ${region.civilization} era. This is predefined fictional lore, not AI output.`,possibleFunction:FUNCTIONS[i%5],conclusion:'Further fictional study is recommended. No physical or on-chain verification exists.',artwork:ART[i%ART.length],artIndex:(ri*10+i)%8})));
const STAGES=['ENTERING ANCIENT RUINS','SCANNING LOST CIVILIZATION','DETECTING UNKNOWN SIGNAL','RECOVERING ARTIFACT','DISCOVERY COMPLETE'];
const state={account:null,provider:null,relics:[],selectedRegion:null,selectedRelic:null,rarity:'',search:'',sort:'latest',running:false,timer:null};
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(location.hostname==='127.0.0.1'&&new URLSearchParams(location.search).has('walletMock')&&!window.ethereum){const n=new URLSearchParams(location.search).get('walletMock')==='2'?'87654321':'12345678',mock=`0x${n.repeat(5)}`.slice(0,42);window.ethereum={request:async({method})=>['eth_accounts','eth_requestAccounts'].includes(method)?[mock]:method==='eth_chainId'?'0x1':null,on:()=>{}}}

function toast(text){const n=$('#toast');n.textContent=text;n.classList.add('show');clearTimeout(n.timer);n.timer=setTimeout(()=>n.classList.remove('show'),3000)}
function storageKey(address){return`relic-zero:local:v1:${address.toLowerCase()}`}
function validRelic(r){return r&&typeof r==='object'&&typeof r.localId==='string'&&typeof r.templateId==='string'&&typeof r.walletAddress==='string'&&REGIONS.some(x=>x.id===r.regionId)&&['COMMON','RARE','EPIC','LEGENDARY','MYTHIC'].includes(r.rarity)&&Number.isFinite(Date.parse(r.discoveredAt))}
function loadCollection(){state.relics=[];if(!state.account)return;try{const raw=JSON.parse(localStorage.getItem(storageKey(state.account))||'[]');state.relics=Array.isArray(raw)?raw.filter(validRelic):[]}catch{toast('Corrupted local collection was ignored safely.')}renderAll()}
function saveCollection(){try{localStorage.setItem(storageKey(state.account),JSON.stringify(state.relics));return true}catch{toast('Browser storage is full. The discovery cannot be saved.');return false}}
function randomUnit(){const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296}
function rarity(){const n=randomUnit()*100;if(n<60)return'COMMON';if(n<85)return'RARE';if(n<95)return'EPIC';if(n<99)return'LEGENDARY';return'MYTHIC'}
function uuid(){return crypto.randomUUID?.()||`local-${Date.now()}-${Math.floor(randomUnit()*1e9)}`}
function pickTemplate(region){const list=TEMPLATES.filter(t=>t.regionId===region.id);return list[Math.floor(randomUnit()*list.length)]}

function installLocalUI(){
 $('#explore .page-intro .kicker').textContent='LOCAL EXPEDITION TERMINAL';
 $('#explore .page-intro>p:last-child').textContent='All five regions are unlocked. Discoveries are stored only in this browser for the connected wallet.';
 $('#analysis .section-head .kicker').textContent='PREDEFINED FICTIONAL ANALYSIS';
 $('#analysis .section-head h1').textContent='ARTIFACT ANALYSIS';
 $('#analysis .section-head>p:last-child').textContent='Preset fictional records reveal materials, history and possible function. No AI service is called.';
 $('#analyzeBtn').textContent='ARTIFACT ANALYSIS';
 $('#expeditionStatus').textContent=state.account?'SELECT A REGION TO BEGIN':'CONNECT WALLET TO EXPLORE';
 $('.detail-actions button').textContent='NFT MINTING NOT AVAILABLE';
 document.body.insertAdjacentHTML('beforeend',`<div class="expedition-overlay" id="expeditionOverlay" aria-hidden="true"><div class="expedition-cinematic"><div class="scan-core"><i></i><i></i><img src="assets/relic/hero-relic.png" alt="Artifact silhouette"></div><p class="kicker">LOCAL EXPEDITION · NO TRANSACTION</p><h2 id="expeditionStage">${STAGES[0]}</h2><div class="stage-track" id="stageTrack">${STAGES.map((_,i)=>`<i class="${i?'':'active'}"></i>`).join('')}</div><button class="btn ghost" id="skipExpedition">SKIP ANIMATION</button></div></div><div class="discovery-modal" id="discoveryModal" aria-hidden="true"><article class="discovery-card panel" id="discoveryCard"><button class="modal-close" id="closeDiscovery" aria-label="Close discovery">×</button><p class="kicker">LOCAL DISCOVERY · NOT AN NFT</p><img id="discoveryImage" src="${ART[0]}" alt="Discovered relic"><span class="badge" id="discoveryRarity">COMMON</span><h2 id="discoveryName">DISCOVERY</h2><dl><div><dt>CIVILIZATION</dt><dd id="discoveryCiv">—</dd></div><div><dt>REGION</dt><dd id="discoveryRegion">—</dd></div><div><dt>MATERIAL</dt><dd id="discoveryMaterial">—</dd></div></dl><p id="discoveryDescription"></p><div class="discovery-actions"><button class="btn ghost" id="viewDiscovery">VIEW RELIC</button><button class="btn primary" id="exploreAgain">EXPLORE AGAIN</button><button class="btn ghost" id="openCollection">MY COLLECTION</button></div></article></div>`);
 $('#skipExpedition').onclick=()=>finishExpedition();$('#closeDiscovery').onclick=closeDiscovery;$('#viewDiscovery').onclick=()=>{closeDiscovery();openRelic(state.selectedRelic)};$('#exploreAgain').onclick=()=>{closeDiscovery();startExpedition()};$('#openCollection').onclick=()=>{closeDiscovery();location.hash='relics'};
}
function route(){const id=(location.hash||'#home').slice(1),target=document.getElementById(id)||$('#home');$$('.view').forEach(v=>v.classList.toggle('active',v===target));$$('.links a').forEach(a=>a.classList.toggle('active',a.hash===`#${target.id}`));$('.links').classList.remove('open');$('#walletMenu').classList.remove('show');scrollTo({top:0,behavior:reduced.matches?'auto':'smooth'});if(id==='leaderboard')renderLeaderboard();if(id==='profile')renderProfile();if(id==='archive')renderArchive()}
function renderRegions(){$('#regionGrid').innerHTML=REGIONS.map((r,i)=>`<button type="button" class="region" data-i="${i}"><span>REGION 0${i+1} · UNLOCKED</span><h3>${r.name}</h3><p>${r.description}</p><small>DIFFICULTY · ${r.difficulty}<br>LOCAL DISCOVERIES · ${state.relics.filter(x=>x.regionId===r.id).length}</small></button>`).join('');$$('.region').forEach(c=>{c.onclick=()=>{state.selectedRegion=REGIONS[+c.dataset.i];$$('.region').forEach(x=>x.classList.toggle('selected',x===c));$('#expeditionTitle').textContent=state.selectedRegion.name;$('#expeditionStatus').textContent=validWallet(state.account)?'Ready. This local expedition requires no signature, transaction or gas.':'CONNECT WALLET TO EXPLORE';renderWallet()}})}
function renderRelics(){const q=state.search.toLowerCase();let rows=state.relics.filter(r=>(!state.rarity||r.rarity===state.rarity)&&(!q||`${r.name} ${r.civilization} ${r.region}`.toLowerCase().includes(q)));rows.sort((a,b)=>(state.sort==='oldest'?1:-1)*(new Date(a.discoveredAt)-new Date(b.discoveredAt)));$('#relicGrid').innerHTML=rows.map(r=>`<article class="relic-card rarity-${r.rarity.toLowerCase()}" data-id="${r.localId}" tabindex="0" role="button"><img class="art-${r.artIndex}" src="${r.artwork}" alt="${safe(r.name)}"><h3>${safe(r.name)}</h3><span class="badge">${r.rarity}</span><p>${safe(r.civilization)} · ${fmtDate(r.discoveredAt)}</p></article>`).join('');$('#relicEmpty').style.display=rows.length?'none':'flex';$('#relicEmpty h2').textContent=state.account?'LOCAL GALLERY AWAITS':'CONNECT WALLET';$('#relicEmpty p').textContent=state.account?'No local discoveries for this wallet yet.':'Each wallet has a separate browser-only collection.';$$('.relic-card').forEach(c=>{const open=()=>openRelic(state.relics.find(r=>r.localId===c.dataset.id));c.onclick=open;c.onkeydown=e=>{if(['Enter',' '].includes(e.key))open()}})}
function openRelic(r){if(!r)return;state.selectedRelic=r;$('#detailImage').src=r.artwork;$('#detailImage').className=`art-${r.artIndex}`;$('#detailName').textContent=r.name;$('#detailRarity').textContent=`${r.rarity} · LOCAL`;$('#detailDescription').textContent=r.description;$('#detailCiv').textContent=r.civilization;$('#detailCategory').textContent=r.category;$('#detailMaterial').textContent=r.material;$('#detailEnergy').textContent=r.energySignature;$('#detailDate').textContent=fmtDate(r.discoveredAt);$('#detailOwner').textContent=short(r.walletAddress);$('#analysisState').textContent=r.name;$('#analysisMessage').textContent='PREDEFINED FICTIONAL ANALYSIS · Select Artifact Analysis to read the preset report.';$('#analyzeBtn').disabled=false;location.hash='relic-detail'}
function renderWallet(){const connected=validWallet(state.account);$('#walletLabel').textContent=short(connected?state.account:null);$('#walletBtn').classList.toggle('connected',connected);$('#profileWallet').textContent=connected?state.account:'NOT CONNECTED';$('#profileChain').textContent=connected?'Local browser collection · no login, signature or transaction required.':'Connect a wallet to load its browser-only collection.';$('#expeditionBtn').disabled=state.running;$('#expeditionBtn').textContent=connected?'START EXPEDITION →':'CONNECT WALLET TO EXPLORE';if(!state.selectedRegion)$('#expeditionStatus').textContent=connected?'SELECT A REGION TO BEGIN':'CONNECT WALLET TO EXPLORE'}
async function connect(){if(validWallet(state.account)){$('#walletMenu').classList.toggle('show');return true}const p=window.ethereum;if(!p){toast('Connect your wallet to explore. No injected EVM wallet was detected.');return false}try{const[a]=await p.request({method:'eth_requestAccounts'});if(!validWallet(a))throw Error('INVALID_ACCOUNT');state.provider=p;state.account=a.toLowerCase();renderWallet();loadCollection();toast('Wallet connected. All regions are unlocked.');return true}catch(e){toast(e?.code===4001?'Wallet connection cancelled.':'Wallet connection failed. Please try again.');return false}}
async function reconnect(){if(!window.ethereum)return;try{const[a]=await ethereum.request({method:'eth_accounts'});if(a){state.provider=ethereum;state.account=a.toLowerCase();renderWallet();loadCollection()}}catch{}}
async function startExpedition(){if(state.running){toast('An expedition is already in progress.');return}try{if(!validWallet(state.account)){toast('Connect your wallet to explore.');if(!await connect())return}if(!state.selectedRegion){toast('Select a civilization first.');return}state.running=true;renderWallet();toast('Entering ancient ruins...');const overlay=$('#expeditionOverlay');overlay.classList.add('show');overlay.setAttribute('aria-hidden','false');let i=0;showStage(i);const speed=reduced.matches?120:1100;state.timer=setInterval(()=>{i++;if(i>=STAGES.length){clearInterval(state.timer);setTimeout(finishExpedition,reduced.matches?20:650)}else showStage(i)},speed)}catch{state.running=false;renderWallet();toast('Exploration failed. Please try again.')}}
function showStage(i){$('#expeditionStage').textContent=STAGES[i];$$('#stageTrack i').forEach((x,n)=>x.classList.toggle('active',n<=i))}
function finishExpedition(){if(!state.running)return;try{clearInterval(state.timer);const t=pickTemplate(state.selectedRegion),r={...t,localId:uuid(),id:uuid(),walletAddress:state.account,rarity:rarity(),discoveredAt:new Date().toISOString(),localOnly:true};state.relics.unshift(r);if(!saveCollection()){state.relics.shift();throw Error('STORAGE_FAILED')}state.selectedRelic=r;state.running=false;$('#expeditionOverlay').classList.remove('show');$('#expeditionOverlay').setAttribute('aria-hidden','true');renderAll();showDiscovery(r);toast('Relic discovered!')}catch(e){state.running=false;$('#expeditionOverlay').classList.remove('show');$('#expeditionOverlay').setAttribute('aria-hidden','true');renderWallet();toast(e?.message==='STORAGE_FAILED'?'Unable to save discovery in this browser.':'Exploration failed. Please try again.')}}
function showDiscovery(r){const card=$('#discoveryCard');card.className=`discovery-card panel rarity-${r.rarity.toLowerCase()}`;$('#discoveryImage').src=r.artwork;$('#discoveryImage').className=`art-${r.artIndex}`;$('#discoveryRarity').textContent=`${r.rarity} · LOCAL`;$('#discoveryName').textContent=r.name;$('#discoveryCiv').textContent=r.civilization;$('#discoveryRegion').textContent=r.region;$('#discoveryMaterial').textContent=r.material;$('#discoveryDescription').textContent=r.description;$('#discoveryModal').classList.add('show');$('#discoveryModal').setAttribute('aria-hidden','false')}
function closeDiscovery(){$('#discoveryModal').classList.remove('show');$('#discoveryModal').setAttribute('aria-hidden','true')}
function renderArchive(){const civs=REGIONS.map(region=>({region,items:state.relics.filter(r=>r.regionId===region.id)}));$('#civilizations').innerHTML=civs.map((x,i)=>`<button class="civ-item" data-i="${i}"><b>${x.region.civilization}</b><small>${x.items.length} LOCAL RELICS · ${x.items.length?'DISCOVERED':'UNDISCOVERED'}</small></button>`).join('');$$('.civ-item').forEach(b=>b.onclick=()=>{const x=civs[+b.dataset.i];$$('.civ-item').forEach(n=>n.classList.toggle('active',n===b));$('#archiveTitle').textContent=x.region.civilization;$('#archiveDescription').textContent=x.items.length?`${x.items.length} local artifacts across ${new Set(x.items.map(r=>r.category)).size} categories. Region history is derived from this wallet's browser collection.`:'No local discoveries from this civilization yet.';$('.progress-orb strong').textContent=`${x.items.length}/10`});$('.archive-progress p').textContent='Progress is calculated only from this connected wallet’s local browser collection.'}
function renderLeaderboard(){$('#leaderRows').className='table-state';$('#leaderRows').innerHTML=`<div><strong>GLOBAL LEADERBOARD COMING SOON</strong><p>Isolated browser collections cannot produce a real global ranking.</p>${state.account?`<p>MY EXPLORATION STATS · ${state.relics.length} discoveries · ${new Set(state.relics.map(r=>r.regionId)).size} regions</p>`:'<p>Connect a wallet to view local exploration stats.</p>'}</div>`}
function renderProfile(){const rs=state.relics;$('#metricRelics').textContent=state.account?rs.length:'—';$('#metricLegendary').textContent=state.account?rs.filter(r=>r.rarity==='LEGENDARY').length:'—';$('#metricCivs').textContent=state.account?new Set(rs.map(r=>r.civilization)).size:'—';$('.profile-page .state-card h2').textContent=state.account?(rs.length?'LOCAL COLLECTION LOADED':'NO LOCAL DISCOVERIES YET'):'CONNECT YOUR EXPLORER IDENTITY';$('.profile-page .state-card p').textContent=state.account?`${rs.length} browser-only discoveries · ${new Set(rs.map(r=>r.regionId)).size} explored regions. No achievements are fabricated.`:'Only wallet-scoped local records will appear here.'}
function analyze(){const r=state.selectedRelic;if(!r)return toast('Select a relic from LOCAL COLLECTION first.');$('#analysisState').textContent='PREDEFINED FICTIONAL ANALYSIS';$('#analysisMessage').innerHTML=`<b>${safe(r.name)}</b><br>MATERIAL · ${safe(r.material)}<br>CIVILIZATION · ${safe(r.civilization)}<br>ENERGY · ${safe(r.energySignature)}<br>HISTORY · ${safe(r.history)}<br>POSSIBLE FUNCTION · ${safe(r.possibleFunction)}<br>CONCLUSION · ${safe(r.conclusion)}`;location.hash='analysis'}
function renderHome(){const rs=state.relics,values=state.account?[rs.length,rs.filter(r=>['LEGENDARY','MYTHIC'].includes(r.rarity)).length,new Set(rs.map(r=>r.civilization)).size,new Set(rs.map(r=>r.regionId)).size]:['—','—','—','—'],labels=state.account?['MY DISCOVERIES','RARE FINDS','MY CIVILIZATIONS','MY REGIONS']:['EXPLORERS','RELICS DISCOVERED','CIVILIZATIONS','ARCHIVE RECORDS'];$$('.stats strong').forEach((n,i)=>n.textContent=values[i]);$$('.stats span').forEach((n,i)=>n.textContent=labels[i]);$('.stats p').textContent=state.account?'LOCAL ONLY':'DATA UNAVAILABLE'}
function renderAll(){renderRegions();if(state.selectedRegion){const i=REGIONS.findIndex(r=>r.id===state.selectedRegion.id);$(`.region[data-i="${i}"]`)?.classList.add('selected')}renderRelics();renderArchive();renderLeaderboard();renderProfile();renderHome();renderWallet()}

installLocalUI();addEventListener('hashchange',route);$('.menu-btn').onclick=()=>$('.links').classList.toggle('open');$('#trailerBtn').onclick=()=>toast('Trailer coming soon.');$('.lang-btn').onclick=()=>toast('English is currently the only available language.');$('#walletBtn').onclick=connect;$('#expeditionBtn').onclick=startExpedition;$('#analyzeBtn').onclick=analyze;$('#relicSearch').oninput=e=>{state.search=e.target.value.trim();renderRelics()};$('#relicSort').onchange=e=>{state.sort=e.target.value;renderRelics()};$$('#rarityFilters button').forEach(b=>b.onclick=()=>{state.rarity=b.dataset.rarity;$$('#rarityFilters button').forEach(x=>x.classList.toggle('active',x===b));renderRelics()});$$('#leaderTabs button').forEach(b=>b.onclick=()=>{$$('#leaderTabs button').forEach(x=>x.classList.toggle('active',x===b));renderLeaderboard()});$$('.detail-tabs button').forEach(b=>b.onclick=()=>{$$('.detail-tabs button').forEach(x=>x.classList.toggle('active',x===b));if(b.textContent==='ANALYSIS')analyze();else if(b.textContent!=='OVERVIEW')toast(`${b.textContent}: no additional local record is available.`)});$$('.profile-tabs button').forEach(b=>b.onclick=()=>{$$('.profile-tabs button').forEach(x=>x.classList.toggle('active',x===b));if(b.textContent!=='MY COLLECTION')toast(`${b.textContent}: no fabricated records are shown.`)});
$('#walletMenu').onclick=async e=>{const a=e.target.dataset.action;if(!a)return;if(a==='profile')location.hash='profile';if(a==='copy'&&state.account){await navigator.clipboard.writeText(state.account);toast('Address copied.')}if(a==='switch')toast('Any EVM network is supported. No chain switch is required.');if(a==='disconnect'){state.account=null;state.provider=null;state.relics=[];state.selectedRelic=null;renderWallet();renderAll();toast('Wallet disconnected. Local data remains stored for that address.')}$('#walletMenu').classList.remove('show')};
if(window.ethereum){ethereum.on?.('accountsChanged',a=>{state.account=a[0]?.toLowerCase()||null;state.selectedRelic=null;renderWallet();loadCollection();toast(state.account?'Wallet account changed. Local collection switched.':'Wallet disconnected.')});ethereum.on?.('chainChanged',()=>toast('Network changed. Local exploration remains available.'))}
renderWallet();renderAll();route();reconnect();
